(function(E){ const x = E["mkt-m2"] = E["mkt-m2"] || {units:{}}; x.units["mkt-8"] = {"grammar":{"id":"c-mkt-8-g","level":"B1","course":"marketing","unit":"mkt-8","title":"Describing change: rise to, fall by, from... to","titleTr":"Değişimi anlatmak: rise to, fall by, from... to","titleFa":"توصیف تغییر: rise to، fall by، from... to","formsTable":{"headers":{"en":["Pattern","Meaning","Example"],"tr":["Yapı","Anlam","Örnek"],"fa":["الگو","معنی","مثال"]},"rows":[["rise / fall to + number","the new level","Leads rose to 120."],["rise / fall by + number","the size of the change","The cost per lead fell by 7 euros."],["from... to...","the start and the end","Leads rose from 40 to 120."],["a rise / a fall of + number","the change, as a noun","a rise of 80 leads"]]},"wrong":"The cost per lead fell with 7 euros.","right":"The cost per lead fell by 7 euros.","blank":{"sentence":"Leads rose from 40 ___ 120 in four weeks.","word":"to","distractors":["by","at"]},"wrong2":"We rose the budget in week two.","right2":"We raised the budget in week two.","blank2":{"sentence":"The cost per lead fell ___ 7 euros, from 12 to 5.","word":"by","distractors":["to","with"]},"expParts":{"rule":[{"en":"to + the new level.","tr":"to + yeni seviye.","fa":"to سطح جدید را می‌گوید.","ex":"Leads rose to 120."},{"en":"by + the size of the change.","tr":"by + değişimin büyüklüğü.","fa":"by اندازه‌ی تغییر را می‌گوید.","ex":"The cost fell by 7 euros."},{"en":"from... to... for the start and the end.","tr":"Başlangıç ve bitiş için from... to....","fa":"from... to... شروع و پایان را می‌گوید.","ex":"from 40 to 120"},{"en":"rise has no object; raise needs one.","tr":"rise nesne almaz; raise nesne ister.","fa":"rise مفعول نمی‌گیرد؛ raise مفعول لازم دارد.","ex":"Leads rose. We raised the budget."}],"test":{"en":"Ask: is the number the new level (to) or the difference (by)?","tr":"Kendine sor: sayı yeni seviye mi (to), yoksa aradaki fark mı (by)?","fa":"از خودت بپرس: عدد سطح جدید است (to) یا تفاوت (by)؟"},"contrast":{"en":"Turkish says \"120'ye çıktı\" for the level and \"7 euro düştü\" for the change, with no word for by; Persian is similar («به ۱۲۰ رسید»، «۷ یورو کم شد»). So learners drop by or guess with.","tr":"Türkçede seviye için \"120'ye çıktı\", değişim için \"7 euro düştü\" deriz; by'ın karşılığı olan bir kelime yoktur. Bu yüzden by düşürülür ya da yerine with kullanılır.","fa":"در فارسی برای سطح می‌گوییم «به ۱۲۰ رسید» و برای تغییر «۷ یورو کم شد»، بدون کلمه‌ای به‌جای by. برای همین by جا می‌افتد یا with جایش می‌نشیند."}},"errorWatch":[{"find":["fell with","rose with","increased with","decreased with","dropped with","we rose the","they rose the","rised"],"fix":{"en":"Use to for the new level and by for the change (\"fell by 7 euros\", \"rose to 120\"). Raise (not rise) takes an object: \"We raised the budget.\"","tr":"Yeni seviye için to, değişim için by kullan (\"fell by 7 euros\", \"rose to 120\"). Nesne alan fiil rise değil raise'dir: \"We raised the budget.\"","fa":"برای سطح جدید to و برای تغییر by بیاور («fell by 7 euros»، «rose to 120»). فعلی که مفعول می‌گیرد raise است، نه rise: «We raised the budget.»"}}]},"b2":{"id":"c-mkt-8-b2","level":"B2","track":"B2","course":"marketing","unit":"mkt-8","title":"Honest approximations: just over, nearly, roughly, well below","titleTr":"Dürüst yaklaşık değerler: just over, nearly, roughly, well below","titleFa":"تقریب صادقانه: just over، nearly، roughly، well below","formsTable":{"headers":{"en":["Exact","Approximate"],"tr":["Kesin","Yaklaşık"],"fa":["دقیق","تقریبی"]},"rows":[["312 leads","just over 300 leads"],["9,800 euros","nearly 10,000 euros"],["113.60 euros","roughly 114 euros"],["5 euros (week one: 12)","well below the 12 euros of week one"]]},"wrong":"The cost per lead was well below of 12 euros.","right":"The cost per lead was well below 12 euros.","blank":{"sentence":"The order was worth ___ 10,000 euros: 9,800, to be exact.","word":"nearly","distractors":["just over","well above"]},"wrong2":"We received just over of 300 leads.","right2":"We received just over 300 leads.","blank2":{"sentence":"We received just ___ 300 leads: 312 in total.","word":"over","distractors":["under","below"]},"useIn":{"en":"B2: in your summary, give one number as an honest approximation (just over, nearly, roughly).","tr":"B2: özetinde bir sayıyı dürüst bir yaklaşık değerle ver (just over, nearly, roughly).","fa":"B2: در خلاصه‌ات یک عدد را با تقریبی صادقانه بیاور (just over، nearly، roughly)."},"exitItem":{"from":"mkt-8","kind":"blank","prompt":"Twenty-one is ___ seven per cent of 312.","options":["roughly","well above","well below"],"correct":0,"why":{"en":"roughly: 21 of 312 is about 6.7%, so 'roughly seven per cent' is honest. 'Well above' and 'well below' would be untrue.","tr":"roughly: 312'nin 21'i yaklaşık %6,7'dir; bu yüzden 'roughly seven per cent' dürüsttür. 'Well above' ve 'well below' doğru olmaz.","fa":"roughly درست است، چون ۲۱ از ۳۱۲ حدود ۶٫۷ درصد است و roughly seven per cent صادقانه است. well above و well below نادرست می‌شوند."}},"expParts":{"tryFrom":"blank","rule":[{"en":"A little more or less: just over / just under.","tr":"Biraz fazla ya da az: just over / just under.","fa":"برای کمی بیشتر یا کمی کمتر، just over یا just under را به کار ببر.","ex":"just over 300 leads (312)"},{"en":"A little less: nearly / almost.","tr":"Biraz az: nearly / almost.","fa":"برای کمی کمتر، nearly یا almost را به کار ببر.","ex":"nearly 10,000 euros (9,800)"},{"en":"Close, either way: roughly / about.","tr":"Yakın, iki yönde de: roughly / about.","fa":"برای نزدیک از هر دو طرف، roughly یا about را به کار ببر.","ex":"roughly 114 euros per buyer"},{"en":"Never round in your own favour.","tr":"Asla işine gelen yöne yuvarlama.","fa":"هرگز به نفع خودت گرد نکن.","ex":"312 is just over 300, not almost 350."}],"test":{"en":"Is the real number above or below your round number? Above: just over. Below: nearly or just under.","tr":"Gerçek sayı yuvarlak sayının üstünde mi altında mı? Üstündeyse just over, altındaysa nearly ya da just under.","fa":"عدد واقعی بالاتر از عدد گرد است یا پایین‌تر؟ بالاتر: just over. پایین‌تر: nearly یا just under."},"contrast":{"en":"Turkish \"yaklaşık\" and Persian «حدود» cover most of these. English also shows the direction: just over (above), nearly (below).","tr":"Türkçedeki \"yaklaşık\" bunların çoğunu karşılar. İngilizce yönü de gösterir: just over (üstünde), nearly (altında).","fa":"«حدود» در فارسی بیشتر این‌ها را می‌پوشاند. انگلیسی جهت را هم نشان می‌دهد: just over (بالاتر)، nearly (پایین‌تر)."}},"errorWatch":[{"find":["well below of","well above of","just over of","just under of","nearly of"],"fix":{"en":"No of after these words: \"just over 300\", \"well below 12 euros\".","tr":"Bu kelimelerden sonra of gelmez: \"just over 300\", \"well below 12 euros\".","fa":"بعد از این کلمه‌ها of نمی‌آید: «just over 300»، «well below 12 euros»."}}]},"vocab":{"id":"c-mkt-8-v","level":"B1","category":"vocab","course":"marketing","unit":"mkt-8","goals":["career"],"title":{"en":"Campaign Numbers","tr":"Kampanya Rakamları","fa":"عددهای کمپین"},"cards":[{"word":"lead","sentence":"A lead is only a name until someone calls it.","meaning":{"en":"A person or company that might become a customer.","tr":"potansiyel müşteri (lead)","fa":"لید (مشتری بالقوه)"}},{"word":"qualified lead","sentence":"Only 21 of the 312 were qualified leads.","gap":"qualified leads","accept":["qualified leads","qualified lead"],"meaning":{"en":"A lead who really can and might buy.","tr":"nitelikli potansiyel müşteri","fa":"لید واجد شرایط"}},{"word":"cost per lead","sentence":"The cost per lead fell, but the leads got worse.","meaning":{"en":"The money spent divided by the number of leads.","tr":"potansiyel müşteri başına maliyet","fa":"هزینه به ازای هر لید"}},{"word":"conversion rate","sentence":"One order from 21 buyers is a conversion rate of about 5%.","meaning":{"en":"The share of people who take the action you want, such as buying.","tr":"dönüşüm oranı","fa":"نرخ تبدیل"}},{"word":"click-through rate","sentence":"The ad had a high click-through rate but few real buyers.","meaning":{"en":"The share of people who click after seeing an ad.","tr":"tıklama oranı","fa":"نرخ کلیک"}},{"word":"impressions","sentence":"The ads made 90,000 impressions in four weeks.","meaning":{"en":"How many times an ad was shown.","tr":"gösterim sayısı","fa":"دفعات نمایش (ایمپرشن)"}},{"word":"vanity metric","sentence":"Likes are a vanity metric if your goal is sign-ups.","meaning":{"en":"A number that looks good but does not help a decision.","tr":"gösteriş metriği","fa":"معیار ظاهری (ونیتی متریک)"}},{"word":"return on investment","sentence":"The return on investment looks better when the second order arrives.","meaning":{"en":"How much you get back compared with what you spent (ROI).","tr":"yatırımın geri dönüşü (ROI)","fa":"بازگشت سرمایه (ROI)"}},{"word":"benchmark","sentence":"We have no benchmark yet, because this was our first campaign.","meaning":{"en":"A number you compare your results with.","tr":"kıyas noktası (benchmark)","fa":"معیار مقایسه (بنچمارک)"}},{"word":"follow up","sentence":"Sales must follow up every lead within 48 hours.","meaning":{"en":"To contact someone again after a first contact.","tr":"takip etmek, geri dönmek","fa":"پیگیری کردن"}}]},"judge":{"id":"c-mkt-8-j","course":"marketing","unit":"mkt-8","type":"judge","title":{"en":"Read the numbers, not the colours","tr":"Renkleri değil rakamları oku","fa":"عددها را بخوان، نه رنگ‌ها را"},"prompt":"Four sentences from reports on three ads. Spend 2,400 euros; 312 forms; 21 real buyers. Free-sample ad: 240 forms, 3 buyers. Tested-fact ad: 52 forms, 14 buyers.","parts":["Accurate","Honest about weak points","Useful next step"],"instruction":{"en":"Tap what each sentence does well. A sentence for your report has all three.","tr":"Her cümlenin iyi yaptığı şeylere dokun. Rapora girecek cümlede üçü de vardır.","fa":"روی کارهایی که هر جمله درست انجام داده بزن. جمله‌ی گزارش باید هر سه را داشته باشد."},"items":[{"by":"AI tool","answer":"Huge success! 312 leads at only 7.69 euros per lead.","present":["Accurate"],"fix":{"en":"The numbers are right, but \"huge success\" hides that only 21 were real buyers. Add the number that matters.","tr":"Rakamlar doğru ama \"huge success\", yalnızca 21 kişinin gerçek alıcı olduğunu gizliyor. Önemli rakamı ekle.","fa":"عددها درست‌اند، ولی «huge success» پنهان می‌کند که فقط ۲۱ نفر خریدار واقعی بودند. عدد مهم را اضافه کن."}},{"by":"AI tool","answer":"Engagement is up 300%!","present":[],"fix":{"en":"Up from what, and why does it matter? Say what changed and what it led to.","tr":"Neye göre artmış ve neden önemli? Neyin değiştiğini ve neye yol açtığını söyle.","fa":"نسبت به چه بالا رفته و چرا مهم است؟ بگو چه چیزی عوض شده و به چه انجامیده."}},{"by":"Good model","answer":"The free-sample ad brought 240 forms but only 3 buyers; the tested-fact ad brought 14 from 52, so next month we will stop free samples.","present":["Accurate","Honest about weak points","Useful next step"],"fix":null},{"by":"Sales manager","answer":"Your leads are students and competitors.","present":["Honest about weak points"],"fix":{"en":"Partly true, but not accurate: 21 were real buyers. Say it with numbers and without blame.","tr":"Kısmen doğru ama kesin değil: 21 kişi gerçek alıcıydı. Rakamlarla ve suçlamadan söyle.","fa":"تا حدی درست است، ولی دقیق نیست: ۲۱ نفر خریدار واقعی بودند. با عدد و بدون سرزنش بگو."}}]},"writing":{"id":"c-mkt-8-w","title":{"en":"A content results note","tr":"Bir içerik sonuç notu","fa":"یادداشت نتایج محتوا"},"course":"marketing","unit":"mkt-8","type":"writing","difficulty":"medium","modelBy":"FEschool","portfolio":"mkt-final-5","prompt":{"en":"Write a results note (80-100 words) on your own recent content, or on this newsletter: goal: trial sign-ups; email A \"Our spring update\": 4,000 sent, 12 sign-ups; email B \"Your first 5K, ten minutes a day\": 4,000 sent, 60 sign-ups; likes on the matching post rose from 80 to 200. Say which piece worked, why, what the weak number was and what you will do next.","tr":"Kendi son içeriğin ya da şu bülten için sonuç notu yaz (80-100 kelime): hedef: deneme kaydı; A e-postası \"Our spring update\": 4.000 gönderim, 12 kayıt; B e-postası \"Your first 5K, ten minutes a day\": 4.000 gönderim, 60 kayıt; ilgili gönderinin beğenileri 80'den 200'e çıktı. Hangi parçanın işe yaradığını, nedenini, zayıf rakamı ve sonra ne yapacağını yaz.","fa":"برای محتوای اخیر خودت یا این خبرنامه یادداشت نتایج بنویس (۸۰ تا ۱۰۰ کلمه): هدف: ثبت‌نام آزمایشی؛ ایمیل A «Our spring update»: ۴٬۰۰۰ ارسال، ۱۲ ثبت‌نام؛ ایمیل B «Your first 5K, ten minutes a day»: ۴٬۰۰۰ ارسال، ۶۰ ثبت‌نام؛ لایک‌های پست مربوط از ۸۰ به ۲۰۰ رسید. بگو کدام کار جواب داد، چرا، عدد ضعیف کدام بود و بعد چه می‌کنی."},"model":"Subject: Spring emails: what worked\n\nOur goal was trial sign-ups. We sent each email to 4,000 readers. Email B brought 60 sign-ups, but email A brought only 12. The subject line is the likely reason: B named the reader's goal, while A talked about us. Likes on the post rose from 80 to 200, but they did not bring sign-ups, so we will not report them as a win. Next month, every subject line will name the reader's goal, and we will test two versions.","frame":"Subject: ___: what worked\n\nOur goal was ___. We sent ___. ___ brought ___, but ___ brought only ___. ___ is the likely reason: ___. ___ rose from ___ to ___, but ___. Next month, ___.","words":[{"word":"rose from"},{"word":"goal"},{"word":"reason"}],"minWords":80,"minSentences":5,"rubric":["Task done: goal, which piece worked, why, weak number, next step","Organised: goal first, then the comparison, why, and the decision","Language: rise and fall with to, by and from... to","Tone: honest and calm; no \"huge success\", no blame"],"rubricI18n":{"tr":["Görev: hedef, hangi parçanın işe yaradığı, nedeni, zayıf rakam, sonraki adım","Düzen: önce hedef, sonra karşılaştırma, neden ve karar","Dil: to, by ve from... to ile rise ve fall","Üslup: dürüst ve sakin; \"huge success\" yok, suçlama yok"],"fa":["کامل بودن کار: هدف، کدام کار جواب داد، چرا، عدد ضعیف، قدم بعدی","نظم: اول هدف، بعد مقایسه، دلیل و تصمیم","زبان: rise و fall با to، by و from... to","لحن: صادق و آرام؛ بدون «huge success» و سرزنش"]}},"speaking":{"id":"mkt-8","course":"marketing","unit":"mkt-8","topic":{"en":"One number for someone who hates numbers","tr":"Rakamları sevmeyen biri için tek bir rakam","fa":"یک عدد برای کسی که از عدد بدش می‌آید"},"warmup":{"en":"Which number do you check most often in your work? Why?","tr":"İşinde en sık hangi rakama bakıyorsun? Neden?","fa":"در کار خودت بیشتر از همه به کدام عدد نگاه می‌کنی؟ چرا؟"},"questions":[{"en":"Explain to your manager why 312 form fills is not the important number.","tr":"Yöneticine 312 formun neden önemli rakam olmadığını anlat.","fa":"برای مدیرت توضیح بده چرا ۳۱۲ فرم عدد مهم نیست."},{"en":"Say which number matters, in plain words.","tr":"Hangi rakamın önemli olduğunu sade kelimelerle söyle.","fa":"با کلمه‌های ساده بگو کدام عدد مهم است."},{"en":"Your manager asks: \"So was it a failure?\" Answer honestly, with one decision.","tr":"Yöneticin soruyor: \"So was it a failure?\" Dürüstçe, bir kararla cevap ver.","fa":"مدیرت می‌پرسد: «So was it a failure?» صادقانه و با یک تصمیم جواب بده."}],"followups":[{"en":"Now explain one number from your own work in under a minute.","tr":"Şimdi kendi işinden bir rakamı bir dakikadan kısa sürede anlat.","fa":"حالا یک عدد از کار خودت را در کمتر از یک دقیقه توضیح بده."},{"en":"Say 13 and 30, then 15 and 50, so that nobody can mix them up: thirTEEN, THIRty. Then give your numbers again.","tr":"13 ve 30, sonra 15 ve 50 sayılarını kimse karıştırmayacak şekilde söyle: thirTEEN, THIRty. Sonra rakamlarını yeniden söyle.","fa":"۱۳ و ۳۰، بعد ۱۵ و ۵۰ را طوری بگو که کسی اشتباه نگیرد: thirTEEN، THIRty. بعد عددهایت را دوباره بگو."}],"expressions":[{"phrase":"The number that matters is...","meaning":{"en":"Points to the one useful number.","tr":"İşe yarayan tek rakamı gösterir.","fa":"همان یک عدد مفید را نشان می‌دهد."}},{"phrase":"In other words,...","meaning":{"en":"Says it more simply.","tr":"Daha sade söyler.","fa":"ساده‌تر می‌گوید."}},{"phrase":"It's not..., but it's not... either.","meaning":{"en":"Gives a balanced, honest answer.","tr":"Dengeli ve dürüst bir cevap verir.","fa":"جوابی متعادل و صادقانه می‌دهد."}}],"model":"312 forms sounds great, but most of them weren't buyers. The number that matters is 21 real buyers. In other words, the free-sample ad brought lots of forms and only 3 buyers, while the tested-fact ad brought 14 from just 52 forms. It's not a failure, but it's not a huge success either. We will stop the free-sample ad next month.","selfCheck":[{"en":"I explained why the big number misleads.","tr":"Büyük rakamın neden yanılttığını anlattım.","fa":"توضیح دادم چرا عدد بزرگ گمراه می‌کند."},{"en":"I gave the number that matters.","tr":"Önemli rakamı söyledim.","fa":"عدد مهم را گفتم."},{"en":"I gave one decision.","tr":"Bir karar söyledim.","fa":"یک تصمیم گفتم."},{"en":"Round 3 fitted in the time.","tr":"3. tur süreye sığdı.","fa":"دور سوم را در زمان تعیین‌شده تمام کردم."}]},"exit":{"id":"c-mkt-8-x","course":"marketing","unit":"mkt-8","type":"exit","items":[{"from":"mkt-8","kind":"blank","prompt":"Our followers increased ___ 500 in one week, from 2,000 to 2,500.","options":["to","by","with"],"correct":1,"point":2,"why":{"en":"by: 'by' gives the size of the change (500). 'To' would give the new total, 2,500, and 'with' doesn't measure change.","tr":"by: 'by' değişimin miktarını verir (500). 'To' yeni toplamı (2.500) verir; 'with' değişimi ölçmez.","fa":"by درست است، چون مقدار تغییر را می‌گوید (۵۰۰). to عدد نهایی یعنی ۲۵۰۰ را می‌گوید و with تغییر را نمی‌سنجد."}},{"from":"mkt-8","kind":"mcq","prompt":"Your goal is newsletter sign-ups. Which number do you report first?","options":["Likes on the post","Total followers","Sign-ups per 100 clicks"],"correct":2,"point":1,"why":{"en":"Sign-ups per 100 clicks: it measures the goal. Likes and total followers can grow while sign-ups don't.","tr":"100 tıklamada kayıt: hedefi ölçer. Beğeniler ve toplam takipçi, kayıtlar artmadan da artabilir.","fa":"ثبت‌نام در هر ۱۰۰ کلیک، چون همان هدف را می‌سنجد. لایک و تعداد کل دنبال‌کننده‌ها ممکن است بالا بروند بدون اینکه ثبت‌نام زیاد شود."}},{"from":"mkt-8","kind":"mcq","prompt":"Which is a fair comparison?","options":["This week's reel against last year's blog","Subject line A against subject line B, same list, same day","Our post against a famous brand's post"],"correct":1,"point":1,"why":{"en":"Subject line A against B, same list, same day: only one thing changes, so the result means something. The other two compare very different things.","tr":"A konu satırına karşı B, aynı liste, aynı gün: yalnızca bir şey değişir, bu yüzden sonuç anlamlıdır. Diğer ikisi çok farklı şeyleri karşılaştırır.","fa":"خط موضوع A در برابر B، با همان فهرست و در همان روز؛ فقط یک چیز عوض می‌شود و نتیجه معنی دارد. دو گزینه‌ی دیگر چیزهای خیلی متفاوت را مقایسه می‌کنند."}},{"from":"mkt-7","kind":"blank","prompt":"The bathrobes ___ certified by an independent body.","options":["have","were be","are"],"correct":2,"point":2,"why":{"en":"are: the robes receive the action, so are + past participle (certified). 'Have certified' says the robes did it, and 'were be' is not English.","tr":"are: bornozlar eylemi alır, bu yüzden are + üçüncü hâl (certified). 'Have certified' işi bornozların yaptığını söyler; 'were be' İngilizce değildir.","fa":"are درست است، چون حوله‌ها گواهی می‌گیرند و are و اسم مفعول لازم است. have certified یعنی خود حوله‌ها گواهی داده‌اند و were be انگلیسی نیست."}},{"from":"mkt-5","kind":"mcq","prompt":"Which line gives proof?","options":["It feels wonderful on your skin.","In a 30-day test with 200 users, 160 kept using it.","You will love it."],"correct":1,"point":1,"why":{"en":"'160 of 200 users kept using it after 30 days' is proof with numbers. 'It feels wonderful' and 'you will love it' are claims.","tr":"'30 günlük testte 200 kullanıcıdan 160'ı kullanmaya devam etti' sayılarla bir kanıttır. 'It feels wonderful' ve 'you will love it' iddiadır.","fa":"«در آزمون ۳۰ روزه ۱۶۰ نفر از ۲۰۰ نفر به استفاده ادامه دادند» مدرکی با عدد است. «It feels wonderful» و «you will love it» ادعا هستند."}},{"from":"mkt-1","kind":"blank","prompt":"We ___ post only on Instagram; now we also have a newsletter.","options":["used to","was used to","use to"],"correct":0,"point":2,"why":{"en":"used to: a past habit, with 'now' showing the change. 'Was used to' means 'was familiar with', and 'use to' needs did.","tr":"used to: geçmiş bir alışkanlık; 'now' değişimi gösterir. 'Was used to' 'alışkındı' demektir; 'use to' did ister.","fa":"used to درست است، چون عادت گذشته است و now تغییر را نشان می‌دهد. was used to یعنی «عادت داشت» و use to did لازم دارد."}}]},"explain":{"id":"c-mkt-8-e","course":"marketing","unit":"mkt-8","type":"explain","level":"B1","title":{"en":"Which content worked, and why","tr":"Hangi içerik işe yaradı, neden?","fa":"کدام محتوا جواب داد و چرا؟"},"objective":{"en":"After this lesson, you can read content results and say which piece worked, why, and what to do next.","tr":"Bu dersin sonunda içerik sonuçlarını okuyup hangi parçanın neden işe yaradığını ve sonra ne yapılacağını söyleyebileceksin.","fa":"بعد از این درس می‌توانی نتایج محتوا را بخوانی و بگویی کدام کار چرا جواب داده و قدم بعدی چیست."},"hook":{"en":"A big number can hide a bad result. To know what worked, start from the piece's goal, read the number for that goal, and end with a decision.","tr":"Büyük bir rakam kötü bir sonucu gizleyebilir. Neyin işe yaradığını anlamak için içeriğin hedefinden başla, o hedefin rakamını oku ve bir kararla bitir.","fa":"یک عدد بزرگ می‌تواند نتیجه‌ی بد را پنهان کند. برای اینکه بفهمی چه چیزی جواب داده، از هدف آن کار شروع کن، عدد مربوط به آن هدف را بخوان و با یک تصمیم تمام کن."},"stats":[{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"3"},{"label":{"en":"Key phrases","tr":"Anahtar ifade","fa":"عبارت کلیدی"},"value":"4"},{"label":{"en":"Practice tasks","tr":"Alıştırma","fa":"تمرین"},"value":"3"}],"points":[{"eyebrow":{"en":"The craft","tr":"Beceri","fa":"مهارت"},"head":{"en":"Read results in four steps","tr":"Sonuçları dört adımda oku","fa":"نتایج را در چهار قدم بخوان"},"steps":[{"en":"Goal first: what was this piece for? Only that goal's number tells you if it worked.","tr":"Önce hedef: Bu içerik ne içindi? İşe yarayıp yaramadığını yalnızca o hedefin rakamı söyler.","fa":"اول هدف: این کار برای چه بود؟ فقط عدد همان هدف می‌گوید جواب داده یا نه.","ex":"Goal: sign-ups. Number: sign-ups per 100 clicks, not likes."},{"en":"Compare similar things: same channel, same length of time. Otherwise the difference may not come from your copy.","tr":"Benzer şeyleri karşılaştır: aynı kanal, aynı süre. Yoksa farkın nedeni metnin olmayabilir.","fa":"چیزهای هم‌ارز را مقایسه کن: همان کانال، همان مدت. وگرنه شاید تفاوت از متن تو نباشد.","ex":"Newsletter subject A against subject B, same list, same day."},{"en":"Ask why: what was different in the words or the offer? Then you can repeat it.","tr":"Nedenini sor: Kelimelerde ya da teklifte ne farklıydı? O zaman bunu tekrar edebilirsin.","fa":"بپرس چرا: در کلمه‌ها یا پیشنهاد چه چیزی فرق داشت؟ آن وقت می‌توانی آن را تکرار کنی.","ex":"Free sample brought 240 forms; only 3 were real buyers."},{"en":"Decide: keep, change or stop, and write it down. A report without a decision changes nothing.","tr":"Karar ver: sürdür, değiştir ya da durdur ve yaz. Karar içermeyen rapor hiçbir şeyi değiştirmez.","fa":"تصمیم بگیر: ادامه بده، عوض کن یا متوقف کن و آن را بنویس. گزارش بدون تصمیم چیزی را عوض نمی‌کند.","ex":"Stop free samples. Keep the tested-fact headline."}],"table":{"headers":{"en":["Ad headline","Forms","Real buyers"],"tr":["Reklam başlığı","Form","Gerçek alıcı"],"fa":["تیتر آگهی","فرم","خریدار واقعی"]},"rows":[["Free towel sample","240","3"],["Tested to 150 washes","52","14"],["Why hotel towels go grey","20","4"]]}},{"eyebrow":{"en":"The language it needs","tr":"Bunun için gereken dil","fa":"زبانی که لازم دارد"},"head":{"en":"Describing change: rise to, fall by, from... to","tr":"Değişimi anlatmak: rise to, fall by, from... to","fa":"توصیف تغییر: rise to، fall by، from... to"},"steps":[{"en":"to + the new level.","tr":"to + yeni seviye.","fa":"to سطح جدید را می‌گوید.","ex":"Leads rose to 120."},{"en":"by + the size of the change.","tr":"by + değişimin büyüklüğü.","fa":"by اندازه‌ی تغییر را می‌گوید.","ex":"The cost fell by 7 euros."},{"en":"from... to... for the start and the end.","tr":"Başlangıç ve bitiş için from... to....","fa":"from... to... شروع و پایان را می‌گوید.","ex":"from 40 to 120"},{"en":"rise has no object; raise needs one.","tr":"rise nesne almaz; raise nesne ister.","fa":"rise مفعول نمی‌گیرد؛ raise مفعول لازم دارد.","ex":"Leads rose. We raised the budget."}],"table":{"headers":{"en":["Pattern","Meaning","Example"],"tr":["Yapı","Anlam","Örnek"],"fa":["الگو","معنی","مثال"]},"rows":[["rise / fall to + number","the new level","Leads rose to 120."],["rise / fall by + number","the size of the change","The cost per lead fell by 7 euros."],["from... to...","the start and the end","Leads rose from 40 to 120."],["a rise / a fall of + number","the change, as a noun","a rise of 80 leads"]]},"tip":{"en":"Turkish says \"120'ye çıktı\" for the level and \"7 euro düştü\" for the change, with no word for by; Persian is similar («به ۱۲۰ رسید»، «۷ یورو کم شد»). So learners drop by or guess with.","tr":"Türkçede seviye için \"120'ye çıktı\", değişim için \"7 euro düştü\" deriz; by'ın karşılığı olan bir kelime yoktur. Bu yüzden by düşürülür ya da yerine with kullanılır.","fa":"در فارسی برای سطح می‌گوییم «به ۱۲۰ رسید» و برای تغییر «۷ یورو کم شد»، بدون کلمه‌ای به‌جای by. برای همین by جا می‌افتد یا with جایش می‌نشیند."},"wrong":"Sales rose with 20% to 1,200.","right":"Sales rose by 20% to 1,200."},{"eyebrow":{"en":"At work","tr":"İş yerinde","fa":"در محیط کار"},"head":{"en":"Saying numbers clearly in a meeting","tr":"Toplantıda rakamları net söylemek","fa":"عددها را در جلسه روشن بگو"},"body":{"en":"People mishear 13 and 30, so stress them: thirTEEN, THIRty. Say what a percentage is a percentage of. Many managers prefer bad news early and with numbers: it costs less trust than a hidden weak result.","tr":"13 ve 30 sık karıştırılır; bu yüzden vurguyu doğru yere koy: thirTEEN, THIRty. Bir yüzdenin neyin yüzdesi olduğunu söyle. Birçok yönetici kötü haberi erken ve rakamlarla duymayı tercih eder: bu, gizlenen zayıf sonuçtan daha az güven kaybettirir.","fa":"13 و 30 را راحت اشتباه می‌شنوند؛ پس تأکید را درست بگذار: thirTEEN، THIRty. بگو درصدِ چه چیزی است. خیلی از مدیرها خبر بد را زود و با عدد ترجیح می‌دهند: این کار کمتر از پنهان کردن نتیجه‌ی ضعیف به اعتماد آسیب می‌زند."},"phrases":[{"phrase":"The number that matters is...","meaning":{"en":"Points to the one useful number.","tr":"İşe yarayan tek rakamı gösterir.","fa":"همان یک عدد مفید را نشان می‌دهد."}},{"phrase":"In other words,...","meaning":{"en":"Says it more simply.","tr":"Daha sade söyler.","fa":"ساده‌تر می‌گوید."}},{"phrase":"It's not..., but it's not... either.","meaning":{"en":"Gives a balanced, honest answer.","tr":"Dengeli ve dürüst bir cevap verir.","fa":"جوابی متعادل و صادقانه می‌دهد."}},{"phrase":"vanity metric","meaning":{"en":"A number that looks good but does not help a decision.","tr":"gösteriş metriği","fa":"معیار ظاهری (ونیتی متریک)"}}]}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"Turn a number into a finding","tr":"Bir rakamı bir bulguya çevir","fa":"یک عدد را به یک نتیجه تبدیل کن"},"item":"Report line: \"Huge success! 312 forms from three ads!\" The data: free-sample ad, 240 forms, 3 buyers; tested-fact ad, 52 forms, 14 buyers; third ad, 20 forms, 4 buyers.","answer":"The tested-fact ad brought only 52 forms, but 14 were real buyers. The free-sample ad brought 240 forms and 3 buyers, probably because people came for the free sample. Next month we will stop the free-sample ad.","walk":[{"en":"Find the goal: real buyers, not form fills.","tr":"Hedefi bul: form sayısı değil, gerçek alıcılar.","fa":"هدف را پیدا کن: خریدار واقعی، نه تعداد فرم."},{"en":"Compare the three ads on that number. Which one won?","tr":"Üç reklamı o rakamla karşılaştır. Hangisi kazandı?","fa":"سه آگهی را با همان عدد مقایسه کن. کدام برنده شد؟"},{"en":"Say why, then write one decision.","tr":"Nedenini söyle, sonra tek bir karar yaz.","fa":"بگو چرا، بعد یک تصمیم بنویس."}]},"quick":{"prompt":"Likes on their own are a ___ metric if your goal is sales.","options":["vanity","conversion","delivery"],"correct":0,"why":{"en":"vanity: a number that looks good but does not tell you if you reached the goal.","tr":"vanity: iyi görünen ama hedefe ulaşıp ulaşmadığını söylemeyen rakam.","fa":"جواب vanity است: عددی که قشنگ به نظر می‌رسد ولی نمی‌گوید به هدف رسیده‌ای یا نه."}},"remember":{"en":"If a number can't change a decision, leave it out of the report. You can now read a results table, say which piece worked and why, and write the decision.","tr":"Bir rakam hiçbir kararı değiştirmiyorsa onu rapora koyma. Artık bir sonuç tablosunu okuyabilir, hangi içeriğin neden işe yaradığını söyleyebilir ve kararı yazabilirsin.","fa":"اگر عددی هیچ تصمیمی را عوض نمی‌کند، آن را در گزارش نیاور. حالا می‌توانی جدول نتایج را بخوانی، بگویی کدام کار چرا جواب داده و تصمیم را بنویسی."},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر B2"},"head":{"en":"Honest approximations: just over, nearly, roughly, well below","tr":"Dürüst yaklaşık değerler: just over, nearly, roughly, well below","fa":"تقریب صادقانه: just over، nearly، roughly، well below"},"steps":[{"en":"A little more or less: just over / just under.","tr":"Biraz fazla ya da az: just over / just under.","fa":"برای کمی بیشتر یا کمی کمتر، just over یا just under را به کار ببر.","ex":"just over 300 leads (312)"},{"en":"A little less: nearly / almost.","tr":"Biraz az: nearly / almost.","fa":"برای کمی کمتر، nearly یا almost را به کار ببر.","ex":"nearly 10,000 euros (9,800)"},{"en":"Close, either way: roughly / about.","tr":"Yakın, iki yönde de: roughly / about.","fa":"برای نزدیک از هر دو طرف، roughly یا about را به کار ببر.","ex":"roughly 114 euros per buyer"},{"en":"Never round in your own favour.","tr":"Asla işine gelen yöne yuvarlama.","fa":"هرگز به نفع خودت گرد نکن.","ex":"312 is just over 300, not almost 350."}],"table":{"headers":{"en":["Exact","Approximate"],"tr":["Kesin","Yaklaşık"],"fa":["دقیق","تقریبی"]},"rows":[["312 leads","just over 300 leads"],["9,800 euros","nearly 10,000 euros"],["113.60 euros","roughly 114 euros"],["5 euros (week one: 12)","well below the 12 euros of week one"]]},"body":{"en":"B2: in your summary, give one number as an honest approximation (just over, nearly, roughly).","tr":"B2: özetinde bir sayıyı dürüst bir yaklaşık değerle ver (just over, nearly, roughly).","fa":"B2: در خلاصه‌ات یک عدد را با تقریبی صادقانه بیاور (just over، nearly، roughly)."}}}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
